{"path": "/tmp/sv-4df037c0dd3842e983c3ad95f5aa3bd7/Components/Pages/Settings/ProfileSection.razor", "file_text": "@namespace sv_4df037c0dd3842e983c3ad95f5aa3bd7.Components.Pages.Settings
@using sv_4df037c0dd3842e983c3ad95f5aa3bd7.Services
@inject ISettingsService SettingsService

<div class="settings-section profile-section">
    <h2>Profile Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading profile...</p>
    }
    else
    {
        <div class="avatar-preview">
            <img src="@_avatarUrl" alt="Avatar" class="avatar-image" />
            <p class="avatar-url">@_avatarUrl</p>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="_displayName" class="form-control" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="_email" class="form-control" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" @bind="_bio" class="form-control" rows="4"></textarea>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveChanges" disabled="@_saving">
                @(_saving ? "Saving..." : "Save Changes")
            </button>
            <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast toast-success">Profile saved successfully!</div>
        }
    }
</div>

@code {
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private UserProfile? _savedProfile;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        _loading = true;
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        _saving = true;
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void DiscardChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
    }
}
"}

{"path": "/tmp/sv-4df037c0dd3842e983c3ad95f5aa3bd7/Components/Pages/Settings/NotificationsSection.razor", "file_text": "@namespace sv_4df037c0dd3842e983c3ad95f5aa3bd7.Components.Pages.Settings
@using sv_4df037c0dd3842e983c3ad95f5aa3bd7.Services
@inject ISettingsService SettingsService

<div class="settings-section notifications-section">
    <h2>Notification Preferences</h2>

    @if (_loading)
    {
        <p class="loading">Loading notification preferences...</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="_emailNotifications" />
                <span class="toggle-label">Email Notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="_pushNotifications" />
                <span class="toggle-label">Push Notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="_weeklyDigest" />
                <span class="toggle-label">Weekly Digest</span>
            </label>
        </div>

        <div class="channels-section">
            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(channel)"
                               @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                        <span>@channel</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SavePreferences" disabled="@_saving">
                @(_saving ? "Saving..." : "Save Preferences")
            </button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast toast-success">Preferences saved successfully!</div>
        }
    }
</div>

@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _allChannels = new() { "general", "announcements", "engineering", "design", "marketing", "random" };
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        _saving = true;
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

{"path": "/tmp/sv-4df037c0dd3842e983c3ad95f5aa3bd7/Components/Pages/Settings/ChangePasswordPanel.razor", "file_text": "@namespace sv_4df037c0dd3842e983c3ad95f5aa3bd7.Components.Pages.Settings
@using sv_4df037c0dd3842e983c3ad95f5aa3bd7.Services
@inject ISettingsService SettingsService

<div class="password-panel">
    <button class="panel-toggle" @onclick="() => _expanded = !_expanded">
        <span class="panel-toggle-icon">@(_expanded ? "▼" : "▶")</span>
        Change Password
    </button>

    @if (_expanded)
    {
        <div class="panel-content">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="_currentPassword" class="form-control" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="_newPassword" class="form-control" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" @bind="_confirmPassword" class="form-control" />
            </div>

            @if (!string.IsNullOrEmpty(_error))
            {
                <div class="alert alert-error">@_error</div>
            }

            @if (_showSuccess)
            {
                <div class="toast toast-success">Password updated successfully!</div>
            }

            <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@_saving">
                @(_saving ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _error = "";
    private bool _saving;
    private bool _showSuccess;

    private async Task UpdatePassword()
    {
        _error = "";
        _showSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _error = "All password fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _error = "New password and confirmation do not match.";
            return;
        }

        _saving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _showSuccess = true;
            _ = HideToastAfterDelay();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

{"path": "/tmp/sv-4df037c0dd3842e983c3ad95f5aa3bd7/Components/Pages/Settings/ActiveSessionsTable.razor", "file_text": "@namespace sv_4df037c0dd3842e983c3ad95f5aa3bd7.Components.Pages.Settings
@using sv_4df037c0dd3842e983c3ad95f5aa3bd7.Services
@inject ISettingsService SettingsService

<div class="sessions-section">
    <h3>Active Sessions</h3>

    @if (Sessions is null || Sessions.Count == 0)
    {
        <p>No active sessions.</p>
    }
    else
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm"
                                        @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="badge badge-current">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }

    @if (_sessionToRevoke is not null)
    {
        <div class="modal-overlay">
            <div class="modal-dialog">
                <h4>Confirm Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                <div class="modal-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevoke" disabled="@_revoking">
                        @(_revoking ? "Revoking..." : "Revoke")
                    </button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<string> OnSessionRevoked { get; set; }

    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is null) return;

        _revoking = true;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        var revokedId = _sessionToRevoke.Id;
        _sessionToRevoke = null;
        _revoking = false;
        await OnSessionRevoked.InvokeAsync(revokedId);
    }
}
"}

{"path": "/tmp/sv-4df037c0dd3842e983c3ad95f5aa3bd7/Components/Pages/Settings/SecuritySection.razor", "file_text": "@namespace sv_4df037c0dd3842e983c3ad95f5aa3bd7.Components.Pages.Settings
@using sv_4df037c0dd3842e983c3ad95f5aa3bd7.Services
@inject ISettingsService SettingsService

<div class="settings-section security-section">
    <h2>Security Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <ChangePasswordPanel />

        <div class="two-factor-section">
            <h3>Two-Factor Authentication</h3>
            <div class="two-factor-status">
                <span class="status-indicator @(_twoFactorEnabled ? "status-enabled" : "status-disabled")">
                    @(_twoFactorEnabled ? "● Enabled" : "○ Disabled")
                </span>
                <label class="toggle-item">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="toggle-label">Enable Two-Factor Authentication</span>
                </label>
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <p class="last-password-change">Last password change: @_lastPasswordChange.Value.ToString("f")</p>
            }
        </div>

        <ActiveSessionsTable Sessions="_sessions"
                             CurrentSessionId="@_currentSessionId"
                             OnSessionRevoked="HandleSessionRevoked" />
    }
</div>

@code {
    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private string _currentSessionId = "";

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
        // Assume first session is current
        _currentSessionId = _sessions.FirstOrDefault()?.Id ?? "";
        _loading = false;
    }

    private void HandleSessionRevoked(string sessionId)
    {
        _sessions = _sessions.Where(s => s.Id != sessionId).ToList();
    }
}
"}

{"path": "/tmp/sv-4df037c0dd3842e983c3ad95f5aa3bd7/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@namespace sv_4df037c0dd3842e983c3ad95f5aa3bd7.Components.Pages.Settings
