+    private List<ActiveSession> _sessions = new();
+    private string _currentSessionId = "";
+
+    protected override async Task OnInitializedAsync()
+    {
+        _loading = true;
+        var settings = await SettingsService.GetSecuritySettingsAsync();
+        _twoFactorEnabled = settings.TwoFactorEnabled;
+        _lastPasswordChange = settings.LastPasswordChange;
+        _sessions = settings.Sessions;
+        // Assume first session is current
+        _currentSessionId = _sessions.FirstOrDefault()?.Id ?? "";
+        _loading = false;
+    }
+
+    private void HandleSessionRevoked(string sessionId)
+    {
+        _sessions = _sessions.Where(s => s.Id != sessionId).ToList();
+    }
+}
+

toolArgs.file_text:
@namespace sv_4df037c0dd3842e983c3ad95f5aa3bd7.Components.Pages.Settings
@using sv_4df037c0dd3842e983c3ad95f5aa3bd7.Services
@inject ISettingsService SettingsService

<div class="settings-section appearance-section">
    <h2>Appearance Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="form-group">
            <h3>Theme</h3>
            <div class="radio-group">
                @foreach (var theme in _themes)
                {
                    <label class="radio-item">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <h3>Font Size</h3>
            <div class="radio-group">
                @foreach (var size in _fontSizes)
                {
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <h3>Language</h3>
            <select @bind="_language" class="form-control">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="form-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="_compactMode" />
                <span class="toggle-label">Compact Mode</span>
            </label>
        </div>

        <div class="preview-area @GetPreviewClasses()">
            <h4>Live Preview</h4>
            <p class="preview-text">This is a preview of your selected appearance settings.</p>
            <div class="preview-card">
                <strong>Sample Card</strong>
                <p>Content appears with your chosen theme, font size, and layout density.</p>
            </div>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                @(_saving ? "Saving..." : "Save")
            </button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast toast-success">Appearance settings saved!</div>
        }
    }
</div>

@code {
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private static readonly string[] _themes = { "Light", "Dark", "System" };
    private static readonly string[] _fontSizes = { "Small", "Medium", "Large" };
    private static readonly string[] _languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_theme.ToLowerInvariant()} preview-font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

