.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: var(--sidebar-bg, #f8f9fa);
    border-right: 1px solid var(--border-color, #dee2e6);
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    margin: 0;
    padding: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.2s, border-left-color 0.2s;
    border-left: 3px solid transparent;
    font-size: 0.95rem;
}

.settings-nav-item:hover {
    background: var(--hover-bg, #e9ecef);
}

.settings-nav-item.active {
    background: var(--active-bg, #e7f1ff);
    border-left-color: var(--primary-color, #0d6efd);
    font-weight: 600;
    color: var(--primary-color, #0d6efd);
}

.settings-nav-icon {
    font-size: 1.1rem;
}

/* Main content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    font-weight: 600;
}

/* Form controls */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    font-size: 0.9rem;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--border-color, #dee2e6);
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: var(--primary-color, #0d6efd);
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.15);
}

textarea.form-control {
    resize: vertical;
}

/* Buttons */
.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.2s, opacity 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: var(--primary-color, #0d6efd);
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-secondary {
    background: #6c757d;
    color: white;
}

.btn-secondary:hover:not(:disabled) {
    background: #5c636a;
}

.btn-danger {
    background: #dc3545;
    color: white;
}

.btn-danger:hover:not(:disabled) {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Toggle items */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    cursor: pointer;
}

.toggle-item input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
    accent-color: var(--primary-color, #0d6efd);
}

.toggle-label {
    font-size: 0.95rem;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.5rem;
    flex-wrap: wrap;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.radio-item input[type="radio"] {
    accent-color: var(--primary-color, #0d6efd);
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: var(--hover-bg, #f8f9fa);
    border-radius: 8px;
}

.avatar-image {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    object-fit: cover;
    background: #dee2e6;
}

.avatar-url {
    font-size: 0.8rem;
    color: #6c757d;
    word-break: break-all;
    margin: 0;
}

/* Channels */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    padding: 0.4rem 0;
}

.channel-item input[type="checkbox"] {
    accent-color: var(--primary-color, #0d6efd);
}

/* Password panel */
.password-panel {
    margin-bottom: 1.5rem;
    border: 1px solid var(--border-color, #dee2e6);
    border-radius: 8px;
    overflow: hidden;
}

.panel-toggle {
    width: 100%;
    padding: 0.85rem 1.25rem;
    background: var(--hover-bg, #f8f9fa);
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
    text-align: left;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.panel-toggle:hover {
    background: #e9ecef;
}

.panel-toggle-icon {
    font-size: 0.75rem;
}

.panel-content {
    padding: 1.25rem;
    border-top: 1px solid var(--border-color, #dee2e6);
}

/* Two-factor */
.two-factor-section {
    margin-bottom: 1.5rem;
}

.two-factor-status {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.status-indicator {
    font-size: 0.9rem;
    font-weight: 500;
}

.status-enabled {
    color: #198754;
}

.status-disabled {
    color: #6c757d;
}

.last-password-change {
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.5rem;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.75rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid var(--border-color, #dee2e6);
    font-size: 0.9rem;
}

.sessions-table th {
    font-weight: 600;
    background: var(--hover-bg, #f8f9fa);
}

.badge {
    padding: 0.2rem 0.6rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 500;
}

.badge-current {
    background: #d1e7dd;
    color: #0f5132;
}

/* Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: white;
    border-radius: 10px;
    padding: 1.5rem 2rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.modal-dialog h4 {
    margin-top: 0;
    margin-bottom: 0.75rem;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
    justify-content: flex-end;
}

/* Preview area */
.preview-area {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 1px solid var(--border-color, #dee2e6);
    border-radius: 8px;
    transition: all 0.3s;
}

.preview-area h4 {
    margin-top: 0;
    margin-bottom: 0.75rem;
}

.preview-card {
    padding: 1rem;
    background: var(--hover-bg, #f8f9fa);
    border-radius: 6px;
    margin-top: 0.75rem;
}

.preview-theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
}

.preview-theme-dark .preview-card {
    background: #2d2d3f;
}

.preview-theme-system {
    background: #f8f9fa;
    color: #212529;
}

.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 0.95rem;
}

.preview-font-large {
    font-size: 1.15rem;
}

.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.4rem;
}

/* Toast */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    animation: fadeIn 0.3s ease-in;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

/* Alert */
.alert {
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.alert-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

/* Loading */
.loading {
    color: #6c757d;
    font-style: italic;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-5px); }
    to { opacity: 1; transform: translateY(0); }
}

